      // home-screen PWA vs Safari tab: the page runs under the status bar only in standalone mode (CSS --ws-top handles the offset)
      if (navigator.standalone || matchMedia('(display-mode: standalone)').matches) document.documentElement.classList.add('standalone');
      // Plain launch: the shard selector is the first screen, with no world or loading panel underneath it.
      const homeParams = new URLSearchParams(location.search);
      if (homeParams.size === 0 || (homeParams.size === 1 && homeParams.has('v'))) document.documentElement.classList.add('title-first');
      // The loader uses a small, already-approved portrait of the selected shard from its first paint.
      // Whitelist the filename: ?chunk is a shard selector, never an arbitrary asset path.
      const loadShard = homeParams.get('chunk') || 'driftwood-isle';
      if (['driftwood-isle', 'pine-hollow', 'nalati-grasslands', 'nine-dragon-stack'].includes(loadShard)) {
        document.documentElement.style.setProperty('--ws-load-portrait', 'url("/assets/title/' + loadShard + '-portrait.jpg")');
      }
      // developer mode (E140, src/engine/core/devMode.ts reads the same key): the loading screen's details, the frame meter, the
      // build id show only under <html data-dev> — set here, before the first paint of the loading panel. No URL switch (E162)
      try { if (JSON.parse(localStorage.getItem('wildshard.save.v2.device') || '{}').keys?.devMode?.data === true) document.documentElement.setAttribute('data-dev', ''); } catch { /* storage blocked: player mode */ }





